// convert upper to lower case for dictionary searching
pub fn upperToLower(x: u8) -> u8 {
	let xx = x;
	match xx {
		0x41 => 0x61,
		0x42 => 0x62,
		0x43 => 0x63,
		0x44 => 0x64,
		0x45 => 0x65,
		0x46 => 0x66,
		0x47 => 0x67,
		0x48 => 0x68,
		0x49 => 0x69,
		0x4A => 0x6A,
		0x4B => 0x6B,
		0x4C => 0x6C,
		0x4D => 0x6D,
		0x4E => 0x6E,
		0x4F => 0x6F,
		0x50 => 0x70,
		0x51 => 0x71,
		0x52 => 0x72,
		0x53 => 0x73,
		0x54 => 0x74,
		0x55 => 0x75,
		0x56 => 0x76,
		0x57 => 0x77,
		0x58 => 0x78,
		0x59 => 0x79,
		0x5A => 0x7A,
		_    => xx,
	}
}

// hasher implementation for dictionary searching
pub struct hasher { p: f64, hsh: f64, p_pow: f64 }
impl hasher {
	pub fn new() -> hasher {
		hasher { p: 111.0, hsh: 0.0, p_pow: 1.0 }
	}
	pub fn reset(&mut self) {
		self.hsh   = 0.0;
		self.p_pow = 1.0;
	}
	pub fn update(&mut self, x: u8) {
		self.hsh = self.hsh + (x as f64 - 32.0 + 1.0) * self.p_pow;
		self.p_pow *= self.p;
	}
	pub fn get(&mut self) -> f64 {
		self.hsh
	}
}
